-- PT126-S4-Q2. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT126-S4-Q2$batch13$ AND q.stimulus=$batch13$It is well documented that people have positive responses to some words, such as “kind” and “wonderful,” and negative responses to others, such as “evil” and “nausea.” Recently, psychological experiments have revealed that people also have positive or negative responses to many nonsense words. This shows that people’s responses to words are conditioned not only by what the words mean, but also by how they sound.$batch13$ AND q.prompt=$batch13$The claim that people have positive or negative responses to many nonsense words plays which one of the following roles in the argument?$batch13$ AND q.correct_choice=$batch13$D$batch13$) THEN RAISE EXCEPTION 'Question changed: PT126-S4-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT126-S4-Q2$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT126-S4-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT126-S4-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$People's responses to words depend not only on what words mean but also on how they sound.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$People respond positively or negatively to some meaningful words. Experiments show people also respond positively or negatively to many nonsense words.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$"This shows" points back to the evidence and introduces the conclusion. Nonsense words have no meaning, so a response to them must come from something else, like sound. The nonsense-word finding is the key premise.$batch13$), (3, $batch13$Goal$batch13$, $batch13$A premise supporting the conclusion about meaning and sound.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT126-S4-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The conclusion isn't that people respond to any word. It's that responses depend on sound as well as meaning.$batch13$), ($batch13$B$batch13$, $batch13$The nonsense-word claim is a premise. Nothing supports it but the experiments.$batch13$), ($batch13$C$batch13$, $batch13$The meaningful-word claim doesn't support it. The two findings sit side by side as evidence.$batch13$), ($batch13$D$batch13$, $batch13$It's a premise, and the conclusion matches: meaning and sound both shape responses.$batch13$), ($batch13$E$batch13$, $batch13$It isn't a conclusion, and nothing contrasts experimental and ordinary situations.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT126-S4-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
